  "judul": "Beban Bunga Gerus Laba, Sokongan Harga Sawit Mengecil",
  "ringkas": "Musim laporan kuartal III 2026 menunjukkan laba masih tumbuh di banyak emiten, tapi beban bunga utang kian menggerus bagian yang sampai ke pemegang saham, sementara sawit mulai kehilangan sokongan harga tinggi yang menopang untungnya sepanjang tahun.",
