    "judul": "Beban bunga jadi penggerus utama laba, bukan cuma kas",
    "isi": "Di tengah pendapatan yang justru tumbuh, laba sejumlah emiten lintas sektor tergerus beban bunga: TBLA labanya turun 6 persen jadi Rp591 miliar meski pendapatan naik 17 persen karena utang bank jangka pendek membesar ke Rp9,62 triliun, BSDE anjlok 38 persen ke Rp844,7 miliar saat utang bank jangka panjangnya naik 18 persen, dan BIRD labanya turun walau pendapatan naik 10,9 persen akibat beban bunga melonjak. KIJA bahkan mencatat laba longsor 78 persen meski pendapatan naik, setelah obligasi Rp3,1 triliun dilunasi dengan pinjaman bank baru. Di ujung paling tegang, WIKA dua kali gagal mendapat restu pemegang obligasi dan sukuknya untuk menunda pembayaran bunga, hanya disetujui 38 persen suara untuk satu usulan dan 2,8 persen untuk tiga usulan lain, sehingga penundaan pembayaran November-Desember tetap berjalan tanpa persetujuan kreditor. Ini melanjutkan pola yang sudah terlihat di edisi lalu soal kas dan utang jangka pendek yang ikut naik bersama laba, hanya sekarang bebannya sudah memotong laba secara langsung. Yang akan menguatkan atau mematahkan arah ini adalah apakah emiten lain menyusul menunda pembayaran utang pada kuartal mendatang, atau laba kuartal IV mulai membaik seiring pelonggaran suku bunga."
