  "judul": "Laba Menebal, Arus Kas Menipis: Tekanan Utang Berlanjut",
  "ringkas": "Laporan keuangan kuartal III yang membanjir hari ini menunjukkan laba yang tumbuh di banyak sektor, tetapi arus kas operasi dan utang jangka pendek ikut terseret naik. Di sektor energi, pemerintah mulai menata ulang siapa yang pegang kendali atas migas.",
