    "isi": "Sejumlah emiten mencatat laba bersih tumbuh dua digit pada sembilan bulan 2026, tetapi arus kas dari kegiatan operasi justru menyusut atau berbalik negatif. KEJU membukukan laba naik 9,2 persen menjadi Rp161,54 miliar, namun arus kas operasinya turun tajam dari Rp224 miliar pada tahun lalu. AXIO mencatat laba naik 74 persen ke Rp61,08 miliar, tetapi arus kas operasinya berbalik negatif Rp97,82 miliar seiring piutang usaha melonjak 126 persen. Pola serupa muncul dari sisi utang, utang bank jangka pendek VICI melonjak dari Rp3 miliar menjadi Rp100 miliar, sementara utang jangka pendek MTDL naik 230 persen untuk membiayai lonjakan persediaan. Arahnya sudah terlihat jelas, pertumbuhan laba kuartal ini di banyak emiten ditopang pembiayaan jangka pendek dan penumpukan piutang atau persediaan, bukan uang tunai yang benar-benar masuk dari bisnis inti. Yang akan menguatkan atau mematahkan pola ini adalah laporan arus kas operasi kuartal IV 2026 awal tahun depan, apakah piutang dan persediaan mulai mengecil atau terus menumpuk."
