  "tanggalLabel": "Selasa, 13 Oktober 2026",
  "judul": "BUMN Karya Tertekan Utang, Pemerintah Pacu Ekspor Lewat CEPA-TEI",
  "ringkas": "Tekanan utang yang kemarin masih berputar di emiten kecil, hari ini menjalar ke tiga BUMN konstruksi sekaligus, sementara pemerintah mendorong tiga jalur ekspor baru hampir bersamaan.",
  "benang": [
   {
    "judul": "Tekanan Utang BUMN Karya Melebar ke Emiten Besar",
    "isi": "PTPP resmi disuspensi BEI sejak 13 Oktober 2026 setelah gagal membayar kupon obligasi dan bagi hasil sukuk yang jatuh tempo sehari sebelumnya, menyusul pemangkasan peringkat Pefindo ke idCCC. Pada hari yang sama, WIKA memanggil rapat pemegang sukuk 28 Oktober untuk meminta penundaan pembayaran bagi hasil, sementara ekuitas Waskita Karya ambruk 71,7 persen jadi Rp1,04 triliun dalam sembilan bulan meski pendapatannya naik 53,7 persen jadi Rp8,13 triliun. BEI juga menjatuhkan sanksi ke 70 emiten, termasuk SRIL dan PGAS, karena telat menyerahkan laporan keuangan. Pola ini melanjutkan dan memperbesar tekanan kas dan tata kelola emiten kecil yang sudah terlihat kemarin, kini merambat ke tiga perusahaan konstruksi pelat merah sekaligus. Yang akan menegaskan atau meredakan arah ini adalah hasil RUPSU WIKA 28 Oktober dan PTPP 10 November soal persetujuan pemegang sukuk, serta apakah suspensi PTPP bisa dicabut."
   },
   {
    "judul": "Tiga Jalur Baru Dipacu untuk Genjot Ekspor",
    "isi": "Pemerintah mendorong implementasi nyata tiga perjanjian dagang dengan Uni Eropa, Kanada, dan Uni Ekonomi Eurasia, yang menurut kajian Kemenko berpotensi menambah ekspor hingga US$14,7 miliar untuk sawit, otomotif, kopi, dan kakao. Bersamaan dengan itu, Trade Expo Indonesia ke-41 dibuka besok dengan calon buyer dari 134 negara dan 1.873 perusahaan peserta, sementara kawasan industri IWIP di Halmahera Tengah memulai ekspor perdana sel baterai litium yang diresmikan Presiden Prabowo Subianto, menandai pergeseran hilirisasi nikel dari bahan setengah jadi ke produk jadi. Ketiganya menunjukkan arah yang sama, fokus pemerintah bergeser dari menandatangani kesepakatan ke memastikan kesepakatan itu benar-benar dipakai eksportir, sejalan dengan neraca dagang yang terus membaik ke surplus US$3,55 miliar pada Agustus. Yang akan menegaskan arah ini adalah nilai transaksi riil yang diumumkan begitu Trade Expo Indonesia 2026 selesai pekan ini."
   },
   {
    "judul": "Akses Dibangun, Kapasitas Pakai Masih Tertinggal",
    "isi": "Program baru ILO-SECO untuk UMKM mengungkap kesenjangan yang masih lebar, survei OJK mencatat 93,6 persen masyarakat sudah punya akses ke layanan keuangan tapi hanya 69,6 persen yang benar-benar paham memakainya secara produktif. Pola serupa muncul saat Mendag dan Menko Pangan meninjau koperasi desa di Sukoharjo, bagian dari pemantauan 107 Koperasi Desa Merah Putih yang sudah berjalan, dan mendapati koperasi Menuran sudah buka sejak Juni namun baru mendapat manajer definitif awal Oktober. Keduanya menunjukkan arah yang sama, perhatian pemerintah bergeser dari sekadar membangun akses atau bangunan menjadi memastikan kapasitas mengelola dan memakainya benar-benar berjalan. Yang akan menunjukkan apakah pergeseran ini konsisten adalah hasil evaluasi menyeluruh terhadap 107 koperasi tersebut dan kelanjutan fase baru program keuangan UMKM pasca PROMISE II."
   }
  ],
  "penutup": "Besok yang paling menentukan adalah pembukaan resmi Trade Expo Indonesia di ICE BSD dan apakah PTPP bisa keluar dari suspensi setelah gagal bayar kupon obligasinya.",
